// src/components/Home.js
import React from 'react';
import './Home.css';
import rocket from '../assets/rocket.png';
import fog from '../assets/fog.webp';

function Home() {
  return (
    <main className="home">
      <section className="hero-section">
        <div className="hero-text">
          <h2>Websites That Truly Drive Results</h2>
          <p>Custom-built web, SaaS, and digital solutions to grow your business.</p>
          <button className="btn-primary">Let’s Talk</button>
        </div>
        <div className="hero-animation">
          <img src={rocket} alt="Rocket" className="rocket" />
          <img src={fog} alt="Fog Trail" className="fog fog-1" />
          <img src={fog} alt="Fog Trail" className="fog fog-2" />
        </div>
      </section>
    </main>
  );
}

export default Home;
